pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    Spy spy;
    function setUp() public {
        spy = new Spy();
        c = new MY_BANK(address(spy));
    }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount > 0);
        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        assertTrue(spy.gotCalled());
    }
}

contract Spy {
    bool public gotCalled;
    function AddMessage(address, uint256, string memory) external {
        gotCalled = true;
    }
}
